      const p = ".obsidian/appearance.json";
      let appJson = {};
      try {
        appJson = JSON.parse(await this.app.vault.adapter.read(p));
      } catch (e) {
        appJson = {};
      }
      const list = Array.isArray(appJson.enabledCssSnippets) ? appJson.enabledCssSnippets : [];
